@layer components {
  :where([data-control-family="item"][data-slot="root"]) {
    --cui-item-radius: var(--radius-control);
    --cui-item-foreground: var(--foreground);
    --cui-item-hover-background: var(--hover-fill);
    --cui-item-current-background: var(--active-fill);
    --cui-item-selected-background: var(--cui-item-current-background);
    --cui-item-selected-foreground: var(--cui-item-foreground);
    --cui-item-dragging-opacity: 0.5;
    --cui-item-drop-target-shadow: inset 0 0 0 var(--focus-ring-width) var(--primary);
    --cui-item-hover-border-color: var(--_item-border-color);
    --cui-item-border-width: 0px;
    --cui-item-active-scale: 0.99;
    --cui-item-gap: calc(var(--spacing) * 3);
    --cui-item-padding-block: calc(var(--spacing) * 3);
    --cui-item-padding-inline: calc(var(--spacing) * 3);
    --cui-item-description-font-size: var(--text-body);
    --cui-item-description-line-height: var(--leading-relaxed);
    --cui-item-description-foreground: var(--muted-foreground);
    --cui-item-media-foreground: var(--muted-foreground);
    --cui-item-media-icon-size: calc(var(--spacing) * 5);
    --_item-background: transparent;
    --_item-border-color: transparent;
    outline: var(--cui-item-border-width) solid var(--_item-border-color);
    outline-offset: calc(-1 * var(--cui-item-border-width));
    border-radius: var(--cui-item-radius);
    background: var(--_item-background);
    box-shadow: none;
    color: var(--cui-item-foreground);
    transition-property: scale;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
    gap: var(--cui-item-gap);
    padding-block: var(--cui-item-padding-block);
    padding-inline: var(--cui-item-padding-inline);
  }

  :where([data-control-family="item"][data-slot="content"]) {
    gap: calc(var(--spacing) * 0.5);
  }

  :where([data-control-family="item"][data-slot="actions"]) {
    gap: calc(var(--spacing) * 1.5);
  }

  @media (hover: hover) and (pointer: fine) {
    :where([data-control-family="item"][data-slot="actions"][data-show-on-hover]) {
      opacity: 0;
      transition: opacity var(--duration-fast) var(--ease-standard);
    }

    :where(
        [data-control-family="item"][data-slot="root"]:is(:hover, :focus-within)
          [data-control-family="item"][data-slot="actions"][data-show-on-hover]
      ),
    :where([data-control-family="item"][data-slot="actions"][data-show-on-hover]:has([data-popup-open])) {
      opacity: 1;
    }
  }

  :where([data-control-family="item"][data-slot="header"]),
  :where([data-control-family="item"][data-slot="footer"]) {
    gap: calc(var(--spacing) * 2);
  }

  :where([data-control-family="item"][data-slot="root"][data-variant="outline"]) {
    --_item-border-color: var(--border);
    --cui-item-border-width: var(--control-rim-width);
  }

  :where([data-control-family="item"][data-slot="root"][data-variant="muted"]) {
    --_item-background: oklch(from var(--muted) l c h / 0.5);
  }

  :where([data-control-family="item"][data-slot="root"][aria-current]:not([aria-current="false"])) {
    --_item-background: var(--cui-item-current-background);
  }

  @media (hover: hover) {
    :where(
        [data-control-family="item"][data-slot="root"]:is(
          a,
          button,
          [href],
          [role="button"],
          [role="treeitem"],
          [role="option"],
          [role="row"],
          [role="menuitem"]
        ):not(:disabled, [data-disabled], [aria-disabled="true"]):hover
      ) {
      outline-color: var(--cui-item-hover-border-color);
      background: var(--cui-item-hover-background);
      box-shadow: none;
    }
  }

  :where([data-control-family="item"][data-slot="root"][aria-selected="true"]) {
    background: var(--cui-item-selected-background);
    color: var(--cui-item-selected-foreground);
  }

  :where([data-control-family="item"][data-slot="root"][data-dragging]) {
    opacity: var(--cui-item-dragging-opacity);
  }

  :where([data-control-family="item"][data-slot="root"][data-drop-target]) {
    box-shadow: var(--cui-item-drop-target-shadow);
  }

  :where([data-control-family="item"][data-slot="root"]:is(:disabled, [data-disabled], [aria-disabled="true"])) {
    cursor: not-allowed;
    opacity: var(--disabled-opacity);
  }

  :where([data-control-family="item"][data-slot="footer"]) {
    font-size: var(--text-caption);
    color: var(--muted-foreground);
  }

  :where(
    [data-control-family="item"][data-slot="root"]:is(a, button, [href], [role="button"]):not(
      :disabled,
      [data-disabled],
      [aria-disabled="true"]
    ):active
  ) {
    scale: var(--cui-item-active-scale);
  }

  :where([data-control-family="item"][data-slot="description"]) {
    font-size: var(--cui-item-description-font-size);
    line-height: var(--cui-item-description-line-height);
    color: var(--cui-item-description-foreground);
    text-wrap: pretty;
  }

  :where([data-control-family="item"][data-slot="title"]) {
    gap: calc(var(--spacing) * 2);
    font-size: var(--text-body);
    font-weight: var(--font-weight-medium);
    line-height: var(--leading-tight);
    text-wrap: balance;
  }

  :where([data-control-family="item"][data-slot="media"]) {
    color: var(--cui-item-media-foreground);
  }

  :where([data-control-family="item"][data-slot="media"] > svg) {
    inline-size: var(--cui-item-media-icon-size);
    block-size: var(--cui-item-media-icon-size);
  }

  @media (forced-colors: active) {
    :where([data-control-family="item"][data-slot="root"][aria-selected="true"]) {
      forced-color-adjust: none;
      background: Highlight;
      color: HighlightText;
    }

    :where(
        [data-control-family="item"][data-slot="root"][aria-selected="true"]
          [data-control-family="item"]:is([data-slot="description"], [data-slot="media"], [data-slot="footer"])
      ) {
      color: HighlightText;
    }

    :where([data-control-family="item"][data-slot="root"][data-drop-target]) {
      outline: var(--focus-ring-width) solid Highlight;
      outline-offset: calc(var(--focus-ring-width) * -1);
    }
  }
}

